{
  "a_requests": [
    {
      "a_request": "R1",
      "b_asked": "청년정책조정위원회 위촉직 9명 중 청년 4명 구성이 조례에 맞는지",
      "c_basis": "DIRECT",
      "d_claims": [
        {
          "a_text": "위촉직 위원 9명 중 청년 4명은 조례에 맞지 않습니다. 제9조제5항은 위촉직 위원에 청년을 2분의 1 이상 포함하도록 정하고 있으므로, 위촉직 9명 중 최소 5명 이상을 청년으로 위촉해야 합니다. 4명은 2분의 1에 미치지 못해 이 요건을 충족하지 못합니다.",
          "b_ids": "청년:제9조제5항"
        }
      ],
      "e_status": "ANSWERED"
    },
    {
      "a_request": "R2",
      "b_asked": "청년정책조정위원회 위촉직 쪽 위원장을 시장이 직접 지명하는 방식이 조례에 맞는지",
      "c_basis": "DIRECT",
      "d_claims": [
        {
          "a_text": "시장이 위촉직 위원 중에서 위원장을 직접 지명하는 방식은 조례에 맞지 않습니다. 제9조제3항은 위원장이 시장과 위촉직 위원 중에서 호선하는 자가 된다고 정하고 있으므로, 위촉직 쪽 위원장은 위촉직 위원들이 호선하여 선출해야 합니다.",
          "b_ids": "청년:제9조제3항"
        }
      ],
      "e_status": "ANSWERED"
    }
  ]
}
